const html = "<!DOCTYPE html>\n\n<html lang=\"en\"><head><meta name=\"referrer\" content=\"strict-origin-when-cross-origin\"/><meta charset=\"utf-8\"/><meta content=\"width=device-width, initial-scale=1\" name=\"viewport\"/><title>Sri Lanka | 4–17 December 2026</title>\n<link crossorigin=\"\" href=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.css\" integrity=\"sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=\" rel=\"stylesheet\"/>\n<style>\n:root{--bg:#f5f6f3;--ink:#182b2b;--muted:#637371;--accent:#146c61;--line:#dce4df;--card:#fff}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:15px/1.6 system-ui,-apple-system,Segoe UI,sans-serif;color:var(--ink)}header{background:#123b38;color:white;padding:48px max(24px,calc((100vw - 1150px)/2)) 42px}header h1{font-size:clamp(30px,5vw,54px);line-height:1.1;margin:8px 0 14px}header p{max-width:720px;color:#d7e7e1;margin:0}.eyebrow{letter-spacing:.14em;text-transform:uppercase;font-size:12px;font-weight:700;color:#95d4bd}.layout{max-width:1200px;margin:26px auto;padding:0 20px;display:grid;grid-template-columns:minmax(0,1fr) 390px;gap:22px}.panel{background:white;border:1px solid var(--line);border-radius:14px;padding:24px;margin-bottom:20px;box-shadow:0 3px 14px #123b3808}h2{font-size:22px;margin:0 0 14px}h3{font-size:17px;margin:0 0 6px}.sub{color:var(--muted);font-size:13px}.stop{border-left:3px solid #c6dcd4;padding:0 0 20px 18px;margin-left:6px;position:relative}.stop:last-child{padding-bottom:0}.stop:before{content:\"\";position:absolute;width:11px;height:11px;background:var(--accent);border:3px solid white;box-shadow:0 0 0 1px var(--accent);border-radius:50%;left:-7px;top:5px}.date{font-weight:700;font-size:12px;color:var(--accent);letter-spacing:.05em}.stop p{margin:4px 0}.pill{display:inline-block;padding:3px 9px;background:#e7f4ef;color:#145e53;border-radius:30px;font-size:12px;margin:5px 4px 0 0}.warn{background:#fff5dd;border-left:4px solid #c68c21;padding:12px 15px;border-radius:6px}.choice{border-top:1px solid var(--line);padding:14px 0}.choice:first-of-type{border:0;padding-top:0}.choice p{margin:3px 0}.mapwrap{position:sticky;top:18px;align-self:start}.map{height:490px;border-radius:10px;overflow:hidden;background:#e8eeea}.mapfallback{display:none}a{color:#146c61}ul{padding-left:20px}li{margin-bottom:7px}footer{max-width:1200px;margin:0 auto;padding:0 20px 30px;color:var(--muted);font-size:12px}.mapkey{display:flex;flex-wrap:wrap;gap:12px;font-size:12px;color:var(--muted);margin-top:12px}.swatch{width:19px;height:4px;display:inline-block;vertical-align:middle;margin-right:5px}.btn{display:inline-block;border:1px solid #b5cbc3;border-radius:8px;padding:7px 10px;text-decoration:none;font-size:13px;margin:8px 6px 0 0}.btn:hover{background:#e9f3ef}body:not(.ready) #map{display:none}body:not(.ready) .mapfallback{display:block;padding:25px;background:#e7eeea;border-radius:10px}@media(max-width:850px){.layout{display:block}.mapwrap{position:static}.map{height:380px}header{padding:34px 22px}}@media print{header{padding:25px}.layout{display:block}.mapwrap{position:static}.panel{break-inside:avoid}body{background:white}}\n\nheader{background:linear-gradient(120deg,#0e3733,#1c5950);padding-top:56px}\nheader h1{font-family:Georgia,serif;font-weight:normal;font-size:clamp(56px,10vw,110px);letter-spacing:-.045em}\nheader nav{display:flex;flex-wrap:wrap;gap:10px 20px;margin-top:24px}\nheader nav a{color:#dcf1e9;text-underline-offset:4px}\n.travellers{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px}\n.travellers>div{background:#eff6f2;border-radius:10px;padding:13px}\n.travellers p{margin:0 0 6px}\n.thread{margin-top:12px;font-size:13px}\n.thread summary{color:#146c61;font-weight:650;cursor:pointer}\n.thread article{background:#eff6f2;border-radius:8px;padding:8px 12px;margin:8px 0}\n.thread article p{white-space:pre-wrap;overflow-wrap:anywhere;margin:2px 0}\n.thread textarea{display:block;width:100%;font:inherit;margin:4px 0 8px;border:1px solid #a2b9af;border-radius:7px;padding:8px}\n.thread button{background:#146c61;color:white;border:0;border-radius:6px;padding:8px 12px;cursor:pointer}\n.thread [role=status]{margin-left:8px}\n@media(max-width:850px){.layout{display:flex;flex-direction:column}.layout aside{order:-1}.layout aside .panel{margin-bottom:0}.map{height:270px}}\n\n.mapfallback svg{display:block;width:100%;max-height:250px;margin-bottom:8px}\n.stop-media{display:grid;grid-template-columns:1fr 1.3fr;gap:12px;margin:12px 0}\n.stop-map,.gallery{min-width:0}\n.stop-map iframe{width:100%;height:165px;border:0;border-radius:9px;background:#e7eeea}\n.stop-map>a,figcaption{font-size:12px;line-height:1.35}\n.slides{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;border-radius:9px;scrollbar-width:thin}\n.slides figure{flex:0 0 100%;min-width:0;scroll-snap-align:start;margin:0}\n.slides img{display:block;width:100%;height:165px;object-fit:cover;background:#e7eeea}\n.slide-controls{display:flex;gap:8px;margin-top:4px}\n.slide-controls button,.selection-comment{border:1px solid #b5cbc3;border-radius:7px;padding:4px 10px;color:#145e53;background:#eff6f2;cursor:pointer}\n.selection-comment{position:fixed;z-index:2000;box-shadow:0 2px 10px #123b3844}\n.thread blockquote{margin:4px 0;padding-left:8px;border-left:3px solid #d49d43;color:#64470a;overflow-wrap:anywhere;cursor:pointer}\n::highlight(commented-text){background:#ffe8a0;color:#182b2b}\n@media(max-width:480px){.stop-media{grid-template-columns:1fr}.stop-map iframe,.slides img{height:150px}}\n\n.local-map{height:210px;border-radius:12px;overflow:hidden;background:#e6efe9;position:relative;isolation:isolate}\n.pin-fallback{height:100%;display:grid;place-content:center;text-align:center;padding:10px;gap:4px;background:repeating-linear-gradient(35deg,#d9e7e0 0 1px,transparent 1px 28px),repeating-linear-gradient(145deg,#d9e7e0 0 1px,transparent 1px 28px)}\n.pin-fallback span{color:#146c61;font-size:24px}\n.pin-fallback small{color:#405c53}\n.local-map .pin-fallback{position:absolute;inset:0;z-index:600;pointer-events:none}\n.local-map.tiles-ready .pin-fallback{display:none}\n.stop-map>a{display:inline-block;margin-top:7px}\n.gallery{background:#f2f7f4;border:1px solid #dce8e0;border-radius:13px;overflow:hidden}\n.slides{border-radius:0;scrollbar-width:none;overscroll-behavior-x:contain}\n.slides img{height:210px}\n.slides figcaption{padding:8px 11px;min-height:44px}\n.slide-controls{align-items:center;gap:6px;padding:0 9px 9px;margin:0}\n.photo-count{font-size:12px;font-variant-numeric:tabular-nums;color:#405c53;white-space:nowrap}\n.photo-dots{display:flex;align-items:center;justify-content:center;flex:1}\n.photo-dots button{padding:0;width:21px;height:25px;border:0;background:transparent;display:grid;place-items:center}\n.photo-dots button::before{content:\"\";width:7px;height:7px;border-radius:50%;background:#8caa9d}\n.photo-dots button[aria-current=true]::before{background:#146c61;width:10px;height:10px}\n.slide-controls [data-step]{padding:0;width:34px;height:32px;background:white;font-size:16px}\n@media(max-width:480px){.local-map,.slides img{height:190px}}\n\n.travel-links{display:flex;flex-wrap:wrap;gap:6px;margin:6px 0 9px}\n.travel-links a{border:1px solid #d4e5dc;background:#f2f8f4;border-radius:20px;padding:3px 9px;font-size:12px;text-decoration:none}\n.travel-links a:hover{text-decoration:underline}\n.day-highlights{border:1px solid #dce8e0;border-radius:9px;padding:8px 10px;margin:10px 0}\n.day-highlights summary{cursor:pointer;font-weight:650;color:#146c61}\n.day-highlights ul{margin:6px 0}\n.option-photo{margin:9px 0 0}\n.option-photo img{display:block;width:min(100%,440px);height:150px;object-fit:cover;border-radius:9px;background:#eff6f2}\n.option-photo figcaption{padding:5px 0}\n.thread .thread-icon{display:inline-flex;align-items:center;gap:4px;color:#146c61;background:#eff6f2;border:1px solid #c0d6cb}\n.comment-box{position:fixed;inset:auto;margin:0;width:min(360px,calc(100vw - 16px));max-height:min(475px,calc(100dvh - 16px));overflow:auto;border:1px solid #b9cfc4;border-radius:12px;padding:13px;background:#fff;color:#182b2b;box-shadow:0 12px 32px #123b3840}\n.comment-heading{display:flex;align-items:center;justify-content:space-between}\n.thread .comment-close{background:#eff6f2;color:#146c61;font-size:18px;padding:2px 9px}\n.comment-box label,.comment-box select{display:block}\n.comment-box select{width:100%;margin:4px 0 8px;padding:6px;border:1px solid #a2b9af;border-radius:7px;background:#fff;color:#182b2b}\n\n.flight-ticket{background:#eff7f3;border:1px solid #c9ded2;border-radius:13px;padding:15px;margin-bottom:12px}\n.flight-leg{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px}\n.flight-leg div{display:grid;gap:3px}\n.flight-leg small{color:#146c61;font-weight:700;letter-spacing:.05em}\n.flight-leg b{font-size:20px}\n.flight-leg span{font-size:13px}\n.day-highlights h4{margin:12px 0 3px}\n.day-alts{background:#eef6f1;border-radius:7px;padding:7px 9px}\n.day-alts strong{display:block}\n.choice[id]{scroll-margin-top:14px}\n.highlight-list>li{margin:0 0 18px}.highlight-list p{margin:7px 0;line-height:1.65}.highlight-list strong{font-size:16px}.day-highlights>details{border-top:1px solid #dce8e0;padding-top:10px}</style><style>select,textarea{max-width:100%;font:inherit}#questionnaire label{display:block;margin:14px 0}#questionnaire textarea{display:block;width:100%;min-height:65px}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:8px;text-align:left;border-bottom:1px solid #dce4df}.variant-note{border-left:3px solid #8062b1;background:#f4effa;padding:10px}.local-map{height:210px}body:not(.ready) #map{display:block}button{cursor:pointer}#copy-output{width:100%;min-height:200px}</style></head><body><header><div class=\"eyebrow\">Family trip · 4–17 December 2026</div><h1>Sri Lanka</h1><p>5–17 December · mountains, culture, wildlife, surfing and diving · two travellers</p><nav aria-label=\"Trip sections\"><a href=\"#flights\">Flights</a><a href=\"#plans\">Plan options</a><a href=\"#itinerary\">Days</a><a href=\"#hiking\">Hiking</a><a href=\"#diving\">Diving</a><a href=\"#questions\">Maria’s questions</a></nav></header>\n<div class=\"layout\"><main>\n<section class=\"panel\" data-thread=\"flights\" id=\"flights\"><h2>Flights · two travellers</h2><div class=\"flight-ticket\"><h3>Maria · IndiGo · Confirmed</h3><div class=\"flight-leg\"><div><small>OUTBOUND · 4–5 DEC</small><b>ATH 14:00 → CMB 08:10 +1</b><span>4 Dec · 6E 1904 ATH 14:00 → BOM 00:35 on 5 Dec<br/>5 Dec · 6E 1185 BOM 05:40 → CMB 08:10</span></div><div><small>RETURN · 12–13 DEC</small><b>CMB 20:05 → ATH 11:55 +1</b><span>12 Dec · 6E 1170 CMB 20:05 → DEL 23:55<br/>13 Dec · 6E 1901 DEL 07:20 → ATH 11:55</span></div></div></div><div class=\"flight-ticket\"><h3>Apostolos · return provisional</h3><p>Working plan starts together on 5 December. Expected departure from Sri Lanka on 17 December. Exact return time and routing await reconfirmation.</p></div><p class=\"warn\">Maria leaves Sri Lanka on 12 December at 20:05. Book a private coast-to-CMB transfer, provisionally around noon, targeting the airport by 16:00. Confirm pickup with the driver and current airline guidance.</p></section>\n<section class=\"panel\" data-thread=\"route\"><h2>Recommended route</h2><p>Begin together in Sigiriya after the overnight flight, then spend a full day among the fortress, Pidurangala and Dambulla’s painted caves. A long road day takes you through Kandy into the highlands. Two nights in Nuwara Eliya leave a dedicated morning for Horton Plains and the World’s End circuit.</p><p>Option A is the provisional working plan. On 9 December Maria heads to the south coast for two full days of surfing or diving, while Apostolos continues to Ella/Haputale for the Pekoe Trail and Ella Rock. Maria flies home on 12 December. Apostolos travels via Udawalawe for a safari, then stays on the coast for diving and a Galle day trip, moving to the airport area on 16 December.</p><p>Both travellers are Advanced Open Water divers. The split, shared dive day, hotels and activities remain proposals.</p></section>\n<section class=\"panel\" data-thread=\"itinerary\" id=\"itinerary\"><h2>Day-by-day working itinerary</h2><div class=\"stop\" data-date=\"5\" data-thread=\"dec-5\"><div class=\"date\">5 DEC · Together</div><h3>Arrival → Sigiriya</h3><p class=\"sub\">Proposed activities · Overnight Sigiriya</p><div class=\"travel-links\"><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Colombo+Bandaranaike+Airport&amp;destination=Sigiriya&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 CMB → Sigiriya (4–5 h)</a><a href=\"#plans\">⇄ Alternatives</a></div><div class=\"stop-media\"><div class=\"stop-map\"><div class=\"local-map\" data-lat=\"7.957\" data-lon=\"80.7603\"></div></div><div aria-label=\"Photos near Sigiriya\" class=\"gallery\" role=\"region\"><div aria-label=\"Swipe or use the arrow keys to browse photos\" class=\"slides\" tabindex=\"0\"><figure><a href=\"https://commons.wikimedia.org/wiki/File:Sigiriya_Rock_Fortress_View_from_Pidurangala_Rock.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Sigiriya from Pidurangala\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Sigiriya_Rock_Fortress_View_from_Pidurangala_Rock.jpg/500px-Sigiriya_Rock_Fortress_View_from_Pidurangala_Rock.jpg\" width=\"500\"/></a><figcaption>Sigiriya from Pidurangala · <a href=\"https://commons.wikimedia.org/wiki/File:Sigiriya_Rock_Fortress_View_from_Pidurangala_Rock.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Negombo_Beach%2C_Sri_Lanka.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Negombo beach\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Negombo_Beach%2C_Sri_Lanka.jpg/500px-Negombo_Beach%2C_Sri_Lanka.jpg\" width=\"500\"/></a><figcaption>Negombo beach · <a href=\"https://commons.wikimedia.org/wiki/File:Negombo_Beach%2C_Sri_Lanka.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Sigiriya_rock_fortress.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Sigiriya Lion Gate\" decoding=\"async\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Sigiriya_rock_fortress.jpg/500px-Sigiriya_rock_fortress.jpg\" width=\"500\"/></a><figcaption>Sigiriya Lion Gate · <a href=\"https://commons.wikimedia.org/wiki/File:Sigiriya_rock_fortress.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure></div><div class=\"slide-controls\"><span aria-live=\"polite\" class=\"photo-count\"></span><div class=\"photo-dots\"></div><button aria-label=\"Previous photo\" data-step=\"-1\" type=\"button\">←</button><button aria-label=\"Next photo\" data-step=\"1\" type=\"button\">→</button></div></div></div><div class=\"day-highlights\"><ul class=\"highlight-list\"><li><strong>Transfer and recover</strong><p>Allow 4–5 hours from CMB after immigration and a food break. Use a pre-arranged driver and leave the afternoon light. An 08:10 arrival does not justify a strenuous climb after an overnight flight.</p></li></ul><details><summary>More Information</summary><p>Accommodation check-in and a quiet meal are enough today. If delayed, sleep near Negombo and move inland early tomorrow.</p><a href=\"#sources\">Sources and checks ↗</a></details></div></div><div class=\"stop\" data-date=\"6\" data-thread=\"dec-6\"><div class=\"date\">6 DEC · Together</div><h3>Sigiriya, Pidurangala and Dambulla</h3><p class=\"sub\">Proposed activities · Overnight Sigiriya</p><div class=\"travel-links\"><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Sigiriya&amp;destination=Dambulla+Cave+Temple&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Sigiriya → Dambulla (30–45 min each way)</a><a href=\"#hiking\">🥾 Pidurangala climb (1–1.5 h return)</a><a href=\"#plans\">⇄ Alternatives</a></div><div class=\"stop-media\"><div class=\"stop-map\"><div class=\"local-map\" data-lat=\"7.957\" data-lon=\"80.7603\"></div></div><div aria-label=\"Photos near Sigiriya and Dambulla\" class=\"gallery\" role=\"region\"><div aria-label=\"Swipe or use the arrow keys to browse photos\" class=\"slides\" tabindex=\"0\"><figure><a href=\"https://commons.wikimedia.org/wiki/File:Sigiriya_Rock_Fortress_View_from_Pidurangala_Rock.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Sigiriya from Pidurangala\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Sigiriya_Rock_Fortress_View_from_Pidurangala_Rock.jpg/500px-Sigiriya_Rock_Fortress_View_from_Pidurangala_Rock.jpg\" width=\"500\"/></a><figcaption>Sigiriya from Pidurangala · <a href=\"https://commons.wikimedia.org/wiki/File:Sigiriya_Rock_Fortress_View_from_Pidurangala_Rock.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Exterior_of_Dambulla_cave_temple_16.JPG\" rel=\"noopener\" target=\"_blank\"><img alt=\"Dambulla cave temples\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Exterior_of_Dambulla_cave_temple_16.JPG/500px-Exterior_of_Dambulla_cave_temple_16.JPG\" width=\"500\"/></a><figcaption>Dambulla cave temples · <a href=\"https://commons.wikimedia.org/wiki/File:Exterior_of_Dambulla_cave_temple_16.JPG\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Sigiriya_rock_fortress.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Sigiriya Lion Gate\" decoding=\"async\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Sigiriya_rock_fortress.jpg/500px-Sigiriya_rock_fortress.jpg\" width=\"500\"/></a><figcaption>Sigiriya Lion Gate · <a href=\"https://commons.wikimedia.org/wiki/File:Sigiriya_rock_fortress.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure></div><div class=\"slide-controls\"><span aria-live=\"polite\" class=\"photo-count\"></span><div class=\"photo-dots\"></div><button aria-label=\"Previous photo\" data-step=\"-1\" type=\"button\">←</button><button aria-label=\"Next photo\" data-step=\"1\" type=\"button\">→</button></div></div></div><div class=\"day-highlights\"><ul class=\"highlight-list\"><li><strong>Explore the Cultural Triangle</strong><p>A full day is feasible with a private vehicle, but three climbs are tiring. Choose Pidurangala sunrise, Sigiriya after breakfast and Dambulla later; alternatively climb Sigiriya first, Dambulla midday and Pidurangala at sunset. Allow roughly 1–1.5 hours, 2–3 hours and 1.5–2 hours respectively, plus driving and meals.</p></li></ul><details><summary>More Information</summary><p>Sigiriya’s summit palace, lion-paw gateway, frescoes and water gardens reward a slow visit. Pidurangala offers a view back towards the fortress; its last section requires scrambling. Dambulla’s cave shrines contain painted ceilings and Buddha statues. Cover shoulders and knees at temples.</p><a href=\"#sources\">Sources and checks ↗</a></details></div></div><div class=\"stop\" data-date=\"7\" data-thread=\"dec-7\"><div class=\"date\">7 DEC · Together</div><h3>Kandy → Nuwara Eliya</h3><p class=\"sub\">Proposed activities · Overnight Nuwara Eliya</p><div class=\"travel-links\"><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Sigiriya&amp;destination=Kandy&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Sigiriya → Kandy (3–4 h)</a><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Kandy&amp;destination=Nuwara+Eliya&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Kandy → Nuwara Eliya (3–4 h)</a><a href=\"#plans\">⇄ Alternatives</a></div><div class=\"stop-media\"><div class=\"stop-map\"><div class=\"local-map\" data-lat=\"6.9497\" data-lon=\"80.7891\"></div></div><div aria-label=\"Photos near Nuwara Eliya\" class=\"gallery\" role=\"region\"><div aria-label=\"Swipe or use the arrow keys to browse photos\" class=\"slides\" tabindex=\"0\"><figure><a href=\"https://commons.wikimedia.org/wiki/File:Tea_Estate_Nuwara_Eliya.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Nuwara Eliya tea estate\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Tea_Estate_Nuwara_Eliya.jpg/500px-Tea_Estate_Nuwara_Eliya.jpg\" width=\"500\"/></a><figcaption>Nuwara Eliya tea estate · <a href=\"https://commons.wikimedia.org/wiki/File:Tea_Estate_Nuwara_Eliya.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Estaci%C3%B3_de_Nanu_Oya.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Nanu Oya station\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Estaci%C3%B3_de_Nanu_Oya.jpg/500px-Estaci%C3%B3_de_Nanu_Oya.jpg\" width=\"500\"/></a><figcaption>Nanu Oya station · <a href=\"https://commons.wikimedia.org/wiki/File:Estaci%C3%B3_de_Nanu_Oya.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Gregory_lake_in_nuwara_eliya.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Gregory Lake\" decoding=\"async\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Gregory_lake_in_nuwara_eliya.jpg/500px-Gregory_lake_in_nuwara_eliya.jpg\" width=\"500\"/></a><figcaption>Gregory Lake · <a href=\"https://commons.wikimedia.org/wiki/File:Gregory_lake_in_nuwara_eliya.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure></div><div class=\"slide-controls\"><span aria-live=\"polite\" class=\"photo-count\"></span><div class=\"photo-dots\"></div><button aria-label=\"Previous photo\" data-step=\"-1\" type=\"button\">←</button><button aria-label=\"Next photo\" data-step=\"1\" type=\"button\">→</button></div></div></div><div class=\"day-highlights\"><ul class=\"highlight-list\"><li><strong>A long highland transfer</strong><p>Allow 3–4 hours Sigiriya–Kandy, then 3–4 hours Kandy–Nuwara Eliya. With a temple visit and lunch this is an 8–10-hour day. Leave early with a private driver.</p></li></ul><details><summary>More Information</summary><p>Visit the Temple of the Tooth only if the road day is on schedule. Drop a tea-factory tour rather than arrive exhausted; tea scenery is visible en route.</p><a href=\"#sources\">Sources and checks ↗</a></details></div></div><div class=\"stop\" data-date=\"8\" data-thread=\"dec-8\"><div class=\"date\">8 DEC · Together · Maria to confirm</div><h3>Horton Plains · World’s End</h3><p class=\"sub\">Proposed activities · Overnight Nuwara Eliya</p><div class=\"travel-links\"><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Nuwara+Eliya&amp;destination=Horton+Plains+National+Park&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Nuwara Eliya → Horton Plains (1.5–2 h each way)</a><a href=\"#hiking\">🥾 Horton Plains circuit (3–4 h)</a><a href=\"#plans\">⇄ Alternatives</a></div><div class=\"stop-media\"><div class=\"stop-map\"><div class=\"local-map\" data-lat=\"6.802\" data-lon=\"80.807\"></div></div><div aria-label=\"Photos near Nuwara Eliya\" class=\"gallery\" role=\"region\"><div aria-label=\"Swipe or use the arrow keys to browse photos\" class=\"slides\" tabindex=\"0\"><figure><a href=\"https://commons.wikimedia.org/wiki/File:Tea_Estate_Nuwara_Eliya.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Nuwara Eliya tea estate\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Tea_Estate_Nuwara_Eliya.jpg/500px-Tea_Estate_Nuwara_Eliya.jpg\" width=\"500\"/></a><figcaption>Nuwara Eliya tea estate · <a href=\"https://commons.wikimedia.org/wiki/File:Tea_Estate_Nuwara_Eliya.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Estaci%C3%B3_de_Nanu_Oya.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Nanu Oya station\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Estaci%C3%B3_de_Nanu_Oya.jpg/500px-Estaci%C3%B3_de_Nanu_Oya.jpg\" width=\"500\"/></a><figcaption>Nanu Oya station · <a href=\"https://commons.wikimedia.org/wiki/File:Estaci%C3%B3_de_Nanu_Oya.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Gregory_lake_in_nuwara_eliya.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Gregory Lake\" decoding=\"async\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Gregory_lake_in_nuwara_eliya.jpg/500px-Gregory_lake_in_nuwara_eliya.jpg\" width=\"500\"/></a><figcaption>Gregory Lake · <a href=\"https://commons.wikimedia.org/wiki/File:Gregory_lake_in_nuwara_eliya.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure></div><div class=\"slide-controls\"><span aria-live=\"polite\" class=\"photo-count\"></span><div class=\"photo-dots\"></div><button aria-label=\"Previous photo\" data-step=\"-1\" type=\"button\">←</button><button aria-label=\"Next photo\" data-step=\"1\" type=\"button\">→</button></div></div></div><div class=\"day-highlights\"><ul class=\"highlight-list\"><li><strong>Walk the cloud-forest circuit</strong><p>Drive roughly 1.5–2 hours each way from Nuwara Eliya, aiming for early entry. The approximately 9 km circuit passes grassland, cloud forest, World’s End and Baker’s Falls. Reserve the whole morning.</p></li></ul><details><summary>More Information</summary><p>Moderate; allow 3–4 hours walking, approximately 200–350 m accumulated ascent depending on track. Start/end at the visitor centre. A guide is optional on the main circuit. Cold rain and mist can obscure the escarpment; avoid exposed edges. Confirm entry permits and operating hours with DWC before departure.</p><a href=\"#sources\">Sources and checks ↗</a></details></div></div><div class=\"stop\" data-date=\"9\" data-thread=\"dec-9\"><div class=\"date\">9 DEC · Apostolos + Maria</div><h3>Proposed split · mountains and coast</h3><p class=\"sub\">Proposed activities · Overnight Ella/Haputale · Maria on coast</p><div class=\"travel-links\"><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Nuwara+Eliya&amp;destination=Ahangama&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Maria · highlands → coast (6–8 h)</a><a href=\"https://seatreservation.railway.gov.lk/mtktwebslr/\" rel=\"noopener\" target=\"_blank\">🚆 Apostolos · Nanu Oya → Ella (timetable pending)</a><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Nanu+Oya&amp;destination=Ella+Sri+Lanka&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Road fallback → Ella (2.5–3.5 h)</a><a href=\"#plans\">⇄ Alternatives</a></div><div class=\"stop-media\"><div class=\"stop-map\"><div class=\"local-map\" data-lat=\"6.8667\" data-lon=\"81.0466\"></div></div><div aria-label=\"Photos near Ella and the rail line\" class=\"gallery\" role=\"region\"><div aria-label=\"Swipe or use the arrow keys to browse photos\" class=\"slides\" tabindex=\"0\"><figure><a href=\"https://commons.wikimedia.org/wiki/File:Estaci%C3%B3_de_Nanu_Oya.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Nanu Oya station\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Estaci%C3%B3_de_Nanu_Oya.jpg/500px-Estaci%C3%B3_de_Nanu_Oya.jpg\" width=\"500\"/></a><figcaption>Nanu Oya station · <a href=\"https://commons.wikimedia.org/wiki/File:Estaci%C3%B3_de_Nanu_Oya.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Nine_Arches_Bridge_in_Ella.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Nine Arch Bridge · Knthabrew\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Nine_Arches_Bridge_in_Ella.jpg/500px-Nine_Arches_Bridge_in_Ella.jpg\" width=\"500\"/></a><figcaption>Nine Arch Bridge · Knthabrew · <a href=\"https://commons.wikimedia.org/wiki/File:Nine_Arches_Bridge_in_Ella.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Ella_Rock%2C_Srilanka.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Ella Rock\" decoding=\"async\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/Ella_Rock%2C_Srilanka.jpg/500px-Ella_Rock%2C_Srilanka.jpg\" width=\"500\"/></a><figcaption>Ella Rock · <a href=\"https://commons.wikimedia.org/wiki/File:Ella_Rock%2C_Srilanka.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure></div><div class=\"slide-controls\"><span aria-live=\"polite\" class=\"photo-count\"></span><div class=\"photo-dots\"></div><button aria-label=\"Previous photo\" data-step=\"-1\" type=\"button\">←</button><button aria-label=\"Next photo\" data-step=\"1\" type=\"button\">→</button></div></div></div><div class=\"day-highlights\"><ul class=\"highlight-list\"><li><strong>Choose separate journeys</strong><p>Maria: private transfer Nuwara Eliya → Ahangama/Weligama, allow 6–8 hours with breaks. Sunset surfing is a bonus. Apostolos: Nanu Oya–Ella train if verified for the day, otherwise allow 2.5–3.5 hours by road.</p></li></ul><details><summary>More Information</summary><p>The split needs Maria’s agreement. Ella is convenient for Ella Rock; Haputale is closer to Stage 13. One Ella base avoids another hotel move but adds roughly 1–1.5 hours each way to Haputale. See the plan selector for alternatives.</p><a href=\"#sources\">Sources and checks ↗</a></details></div></div><div class=\"stop\" data-date=\"10\" data-thread=\"dec-10\"><div class=\"date\">10 DEC · Separate activities</div><h3>Pekoe Stage 13 · Maria surfing</h3><p class=\"sub\">Proposed activities · Overnight Ella/Haputale · Maria on coast</p><div class=\"travel-links\"><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Ella+Sri+Lanka&amp;destination=Haputale&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Ella → Haputale (1–1.5 h each way)</a><a href=\"#hiking\">🥾 Stage 13 (5–6 h)</a><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Ahangama&amp;destination=Midigama&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🛺 Maria · between surf towns (10–30 min)</a><a href=\"#plans\">⇄ Alternatives</a></div><div class=\"stop-media\"><div class=\"stop-map\"><div class=\"local-map\" data-lat=\"6.768\" data-lon=\"80.958\"></div></div><div aria-label=\"Photos near Ella and the rail line\" class=\"gallery\" role=\"region\"><div aria-label=\"Swipe or use the arrow keys to browse photos\" class=\"slides\" tabindex=\"0\"><figure><a href=\"https://commons.wikimedia.org/wiki/File:Estaci%C3%B3_de_Nanu_Oya.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Nanu Oya station\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Estaci%C3%B3_de_Nanu_Oya.jpg/500px-Estaci%C3%B3_de_Nanu_Oya.jpg\" width=\"500\"/></a><figcaption>Nanu Oya station · <a href=\"https://commons.wikimedia.org/wiki/File:Estaci%C3%B3_de_Nanu_Oya.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Nine_Arches_Bridge_in_Ella.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Nine Arch Bridge · Knthabrew\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Nine_Arches_Bridge_in_Ella.jpg/500px-Nine_Arches_Bridge_in_Ella.jpg\" width=\"500\"/></a><figcaption>Nine Arch Bridge · Knthabrew · <a href=\"https://commons.wikimedia.org/wiki/File:Nine_Arches_Bridge_in_Ella.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Ella_Rock%2C_Srilanka.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Ella Rock\" decoding=\"async\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/Ella_Rock%2C_Srilanka.jpg/500px-Ella_Rock%2C_Srilanka.jpg\" width=\"500\"/></a><figcaption>Ella Rock · <a href=\"https://commons.wikimedia.org/wiki/File:Ella_Rock%2C_Srilanka.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure></div><div class=\"slide-controls\"><span aria-live=\"polite\" class=\"photo-count\"></span><div class=\"photo-dots\"></div><button aria-label=\"Previous photo\" data-step=\"-1\" type=\"button\">←</button><button aria-label=\"Next photo\" data-step=\"1\" type=\"button\">→</button></div></div></div><div class=\"day-highlights\"><ul class=\"highlight-list\"><li><strong>Haputale → St Catherine</strong><p>Apostolos: 14.6 km, 810 m ascent and 360 m descent. Official duration 4 hours; budget 5–6 hours with breaks and wet footing. Arrange pickup at St Catherine before setting out.</p></li></ul><details><summary>More Information</summary><p>Official rating is moderate, but this is a substantial hill day. Take offline navigation; a guide is sensible in low visibility. Current advisory reports overgrowth and leeches. Maria: assess Lazy Left/Right or Kabalana with a local surf guide, choosing the break for the actual swell and tide.</p><a href=\"#sources\">Sources and checks ↗</a></details></div></div><div class=\"stop\" data-date=\"11\" data-thread=\"dec-11\"><div class=\"date\">11 DEC · Separate · shared dive alternative</div><h3>Ella Rock · Maria surfing or diving</h3><p class=\"sub\">Proposed activities · Overnight Ella/Haputale · Maria on coast</p><div class=\"travel-links\"><a href=\"#hiking\">🥾 Ella Rock hike (4–6 h)</a><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Ahangama&amp;destination=Unawatuna&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Maria · Ahangama → Unawatuna (30–60 min)</a><a href=\"#plans\">⇄ Alternatives</a></div><div class=\"stop-media\"><div class=\"stop-map\"><div class=\"local-map\" data-lat=\"6.849\" data-lon=\"81.041\"></div></div><div aria-label=\"Photos near Ella\" class=\"gallery\" role=\"region\"><div aria-label=\"Swipe or use the arrow keys to browse photos\" class=\"slides\" tabindex=\"0\"><figure><a href=\"https://commons.wikimedia.org/wiki/File:Nine_Arches_Bridge_in_Ella.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Nine Arch Bridge · Knthabrew\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Nine_Arches_Bridge_in_Ella.jpg/500px-Nine_Arches_Bridge_in_Ella.jpg\" width=\"500\"/></a><figcaption>Nine Arch Bridge · Knthabrew · <a href=\"https://commons.wikimedia.org/wiki/File:Nine_Arches_Bridge_in_Ella.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Little_Adam%27s_peak%2CElla%2CSrilanka.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Little Adam’s Peak · Sanduni Dissanayake\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Little_Adam%27s_peak%2CElla%2CSrilanka.jpg/500px-Little_Adam%27s_peak%2CElla%2CSrilanka.jpg\" width=\"500\"/></a><figcaption>Little Adam’s Peak · Sanduni Dissanayake · <a href=\"https://commons.wikimedia.org/wiki/File:Little_Adam%27s_peak%2CElla%2CSrilanka.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Ella_Rock%2C_Srilanka.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Ella Rock\" decoding=\"async\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/Ella_Rock%2C_Srilanka.jpg/500px-Ella_Rock%2C_Srilanka.jpg\" width=\"500\"/></a><figcaption>Ella Rock · <a href=\"https://commons.wikimedia.org/wiki/File:Ella_Rock%2C_Srilanka.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Ravana_Falls_Ella.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Ravana Falls near Ella\" decoding=\"async\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/Ravana_Falls_Ella.jpg/500px-Ravana_Falls_Ella.jpg\" width=\"500\"/></a><figcaption>Ravana Falls near Ella · <a href=\"https://commons.wikimedia.org/wiki/File:Ravana_Falls_Ella.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure></div><div class=\"slide-controls\"><span aria-live=\"polite\" class=\"photo-count\"></span><div class=\"photo-dots\"></div><button aria-label=\"Previous photo\" data-step=\"-1\" type=\"button\">←</button><button aria-label=\"Next photo\" data-step=\"1\" type=\"button\">→</button></div></div></div><div class=\"day-highlights\"><ul class=\"highlight-list\"><li><strong>A full hiking morning or a shared dive</strong><p>Apostolos: arrange a road-access Ella Rock hike with a local guide that avoids walking active railway tracks. Budget 4–6 hours; approximately 8–12 km and 400–600 m ascent depend on the confirmed route.</p></li></ul><details><summary>More Information</summary><p>Trailhead/end must be confirmed with the guide; do not use the common railway approach. Nine Arch Bridge is optional afterwards. Maria chooses surfing OR a morning dive at Unawatuna/Hikkaduwa. Finish all dives by 20:05 at the absolute latest on 11 December to retain 24 hours before flight; a morning finish gives more margin. Option C requires transferring to the coast on 10 December and giving up or moving a mountain hike.</p><a href=\"#sources\">Sources and checks ↗</a></details></div></div><div class=\"stop\" data-date=\"12\" data-thread=\"dec-12\"><div class=\"date\">12 DEC · Separate journeys</div><h3>Maria flies home · Udawalawe safari</h3><p class=\"sub\">Proposed activities · Overnight Apostolos on south coast</p><div class=\"travel-links\"><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Ahangama&amp;destination=Colombo+Bandaranaike+Airport&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Maria · coast → CMB (3–4 h + buffer)</a><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Ella+Sri+Lanka&amp;destination=Udawalawe&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Ella → Udawalawe (2.5–3.5 h)</a><a href=\"#practical\">🚙 Safari jeep (about 3 h)</a><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Udawalawe&amp;destination=Unawatuna&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Udawalawe → coast (2.5–3.5 h)</a><a href=\"#plans\">⇄ Alternatives</a></div><div class=\"stop-media\"><div class=\"stop-map\"><div class=\"local-map\" data-lat=\"6.438\" data-lon=\"80.889\"></div></div><div aria-label=\"Photos near Tissamaharama safari base\" class=\"gallery\" role=\"region\"><div aria-label=\"Swipe or use the arrow keys to browse photos\" class=\"slides\" tabindex=\"0\"><figure><a href=\"https://commons.wikimedia.org/wiki/File:Elephant_Herd_Yala_National_Park.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Elephant herd in Yala\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Elephant_Herd_Yala_National_Park.jpg/500px-Elephant_Herd_Yala_National_Park.jpg\" width=\"500\"/></a><figcaption>Elephant herd in Yala · <a href=\"https://commons.wikimedia.org/wiki/File:Elephant_Herd_Yala_National_Park.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Sri_Lankan_elephant_%28Elephas_maximus_maximus%29_female_and_young_1.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Sri Lankan elephant and calf\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Sri_Lankan_elephant_%28Elephas_maximus_maximus%29_female_and_young_1.jpg/500px-Sri_Lankan_elephant_%28Elephas_maximus_maximus%29_female_and_young_1.jpg\" width=\"500\"/></a><figcaption>Sri Lankan elephant and calf · <a href=\"https://commons.wikimedia.org/wiki/File:Sri_Lankan_elephant_%28Elephas_maximus_maximus%29_female_and_young_1.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Elephas_maximus_maximus.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Yala wildlife\" decoding=\"async\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Elephas_maximus_maximus.jpg/500px-Elephas_maximus_maximus.jpg\" width=\"500\"/></a><figcaption>Yala wildlife · <a href=\"https://commons.wikimedia.org/wiki/File:Elephas_maximus_maximus.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure></div><div class=\"slide-controls\"><span aria-live=\"polite\" class=\"photo-count\"></span><div class=\"photo-dots\"></div><button aria-label=\"Previous photo\" data-step=\"-1\" type=\"button\">←</button><button aria-label=\"Next photo\" data-step=\"1\" type=\"button\">→</button></div></div></div><div class=\"day-highlights\"><ul class=\"highlight-list\"><li><strong>Airport transfer and safari logistics</strong><p>Maria: optional short surf, checkout and private transfer around noon; allow 3–4 hours plus buffer to CMB and target 16:00 for the 20:05 flight. No diving today.</p></li></ul><details><summary>More Information</summary><p>Apostolos: Ella–Udawalawe takes roughly 2.5–3.5 hours, safari 3 hours, then 2.5–3.5 hours to the coast. This is a 9–11-hour day with stops. Leave early and book the jeep timing; if delayed, stay near Udawalawe and accept losing the morning dive on 13 December.</p><a href=\"#sources\">Sources and checks ↗</a></details></div></div><div class=\"stop\" data-date=\"13\" data-thread=\"dec-13\"><div class=\"date\">13 DEC · Apostolos</div><h3>South-coast reef and wreck diving</h3><p class=\"sub\">Proposed activities · Overnight South coast</p><div class=\"travel-links\"><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Ahangama&amp;destination=Unawatuna&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Ahangama → Unawatuna (30–60 min)</a><a href=\"#diving\">🚤 Dive boat (operator to confirm)</a><a href=\"#plans\">⇄ Alternatives</a></div><div class=\"stop-media\"><div class=\"stop-map\"><div class=\"local-map\" data-lat=\"6.01\" data-lon=\"80.249\"></div></div><div aria-label=\"Photos near Mirissa and the south coast\" class=\"gallery\" role=\"region\"><div aria-label=\"Swipe or use the arrow keys to browse photos\" class=\"slides\" tabindex=\"0\"><figure><a href=\"https://commons.wikimedia.org/wiki/File:Aerial_view_of_Mirissa_beach%2C_Srilanka.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Mirissa beach\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Aerial_view_of_Mirissa_beach%2C_Srilanka.jpg/500px-Aerial_view_of_Mirissa_beach%2C_Srilanka.jpg\" width=\"500\"/></a><figcaption>Mirissa beach · <a href=\"https://commons.wikimedia.org/wiki/File:Aerial_view_of_Mirissa_beach%2C_Srilanka.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Elephant_Herd_Yala_National_Park.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Elephant herd in Yala\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Elephant_Herd_Yala_National_Park.jpg/500px-Elephant_Herd_Yala_National_Park.jpg\" width=\"500\"/></a><figcaption>Elephant herd in Yala · <a href=\"https://commons.wikimedia.org/wiki/File:Elephant_Herd_Yala_National_Park.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Coconut_Tree_Hill.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Coconut Tree Hill\" decoding=\"async\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Coconut_Tree_Hill.jpg/500px-Coconut_Tree_Hill.jpg\" width=\"500\"/></a><figcaption>Coconut Tree Hill · <a href=\"https://commons.wikimedia.org/wiki/File:Coconut_Tree_Hill.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Amazing_Coconut_Tree_Hill.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"View over Mirissa Bay\" decoding=\"async\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Amazing_Coconut_Tree_Hill.jpg/500px-Amazing_Coconut_Tree_Hill.jpg\" width=\"500\"/></a><figcaption>View over Mirissa Bay · <a href=\"https://commons.wikimedia.org/wiki/File:Amazing_Coconut_Tree_Hill.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure></div><div class=\"slide-controls\"><span aria-live=\"polite\" class=\"photo-count\"></span><div class=\"photo-dots\"></div><button aria-label=\"Previous photo\" data-step=\"-1\" type=\"button\">←</button><button aria-label=\"Next photo\" data-step=\"1\" type=\"button\">→</button></div></div></div><div class=\"day-highlights\"><ul class=\"highlight-list\"><li><strong>Dive from Unawatuna</strong><p>Use Unawatuna as the practical diving base after Maria leaves, or stay near Ahangama if surfing is also a priority. Choose two recreational dives with a local operator based on conditions and recent experience.</p></li></ul><details><summary>More Information</summary><p>Galle Ship Wreck around 18 m and SS Orestes around 22 m are useful candidates. Rangoon is reported at 30–32 m and may exceed a 30 m AOW limit. Keep dives within training, no-decompression and operator limits; no penetration or overhead diving.</p><a href=\"#sources\">Sources and checks ↗</a></details></div></div><div class=\"stop\" data-date=\"14\" data-thread=\"dec-14\"><div class=\"date\">14 DEC · Apostolos</div><h3>Diving or a weather-flexible coast day</h3><p class=\"sub\">Proposed activities · Overnight South coast</p><div class=\"travel-links\"><a href=\"#diving\">🚤 Dive boat (operator to confirm)</a><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Unawatuna&amp;destination=Hikkaduwa&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Hikkaduwa alternative (1–1.5 h each way)</a><a href=\"#plans\">⇄ Alternatives</a></div><div class=\"stop-media\"><div class=\"stop-map\"><div class=\"local-map\" data-lat=\"6.01\" data-lon=\"80.249\"></div></div><div aria-label=\"Photos near Mirissa and the south coast\" class=\"gallery\" role=\"region\"><div aria-label=\"Swipe or use the arrow keys to browse photos\" class=\"slides\" tabindex=\"0\"><figure><a href=\"https://commons.wikimedia.org/wiki/File:Aerial_view_of_Mirissa_beach%2C_Srilanka.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Mirissa beach\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Aerial_view_of_Mirissa_beach%2C_Srilanka.jpg/500px-Aerial_view_of_Mirissa_beach%2C_Srilanka.jpg\" width=\"500\"/></a><figcaption>Mirissa beach · <a href=\"https://commons.wikimedia.org/wiki/File:Aerial_view_of_Mirissa_beach%2C_Srilanka.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Elephant_Herd_Yala_National_Park.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Elephant herd in Yala\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Elephant_Herd_Yala_National_Park.jpg/500px-Elephant_Herd_Yala_National_Park.jpg\" width=\"500\"/></a><figcaption>Elephant herd in Yala · <a href=\"https://commons.wikimedia.org/wiki/File:Elephant_Herd_Yala_National_Park.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Coconut_Tree_Hill.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Coconut Tree Hill\" decoding=\"async\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Coconut_Tree_Hill.jpg/500px-Coconut_Tree_Hill.jpg\" width=\"500\"/></a><figcaption>Coconut Tree Hill · <a href=\"https://commons.wikimedia.org/wiki/File:Coconut_Tree_Hill.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Amazing_Coconut_Tree_Hill.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"View over Mirissa Bay\" decoding=\"async\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Amazing_Coconut_Tree_Hill.jpg/500px-Amazing_Coconut_Tree_Hill.jpg\" width=\"500\"/></a><figcaption>View over Mirissa Bay · <a href=\"https://commons.wikimedia.org/wiki/File:Amazing_Coconut_Tree_Hill.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure></div><div class=\"slide-controls\"><span aria-live=\"polite\" class=\"photo-count\"></span><div class=\"photo-dots\"></div><button aria-label=\"Previous photo\" data-step=\"-1\" type=\"button\">←</button><button aria-label=\"Next photo\" data-step=\"1\" type=\"button\">→</button></div></div></div><div class=\"day-highlights\"><ul class=\"highlight-list\"><li><strong>Keep a second dive window</strong><p>If visibility and sea state cooperate, explore another reef or wreck. Otherwise use the day for Galle’s museums, coastal walks or rest rather than driving to a distant attraction.</p></li></ul><details><summary>More Information</summary><p>Hikkaduwa is an alternative if its operator offers a worthwhile site, but allow roughly 1–1.5 hours each way from Unawatuna. Avoid strenuous highland travel after diving; remain on the coast.</p><a href=\"#sources\">Sources and checks ↗</a></details></div></div><div class=\"stop\" data-date=\"15\" data-thread=\"dec-15\"><div class=\"date\">15 DEC · Apostolos</div><h3>Galle Fort day trip</h3><p class=\"sub\">Proposed activities · Overnight Same south-coast base</p><div class=\"travel-links\"><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Unawatuna&amp;destination=Galle+Fort&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Unawatuna → Galle (15–30 min each way)</a><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Ahangama&amp;destination=Galle+Fort&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Ahangama → Galle (40–60 min each way)</a><a href=\"#practical\">🚶 Galle visit (3–5 h)</a><a href=\"#plans\">⇄ Alternatives</a></div><div class=\"stop-media\"><div class=\"stop-map\"><div class=\"local-map\" data-lat=\"6.0269\" data-lon=\"80.217\"></div></div><div aria-label=\"Photos near Galle Fort\" class=\"gallery\" role=\"region\"><div aria-label=\"Swipe or use the arrow keys to browse photos\" class=\"slides\" tabindex=\"0\"><figure><a href=\"https://commons.wikimedia.org/wiki/File:SL_Galle_Fort_asv2020-01_img24.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Galle Fort lighthouse\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/SL_Galle_Fort_asv2020-01_img24.jpg/500px-SL_Galle_Fort_asv2020-01_img24.jpg\" width=\"500\"/></a><figcaption>Galle Fort lighthouse · <a href=\"https://commons.wikimedia.org/wiki/File:SL_Galle_Fort_asv2020-01_img24.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Galle_Fort%2C_Sri_Lanka.JPG\" rel=\"noopener\" target=\"_blank\"><img alt=\"Galle Fort\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/Galle_Fort%2C_Sri_Lanka.JPG/500px-Galle_Fort%2C_Sri_Lanka.JPG\" width=\"500\"/></a><figcaption>Galle Fort · <a href=\"https://commons.wikimedia.org/wiki/File:Galle_Fort%2C_Sri_Lanka.JPG\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure></div><div class=\"slide-controls\"><span aria-live=\"polite\" class=\"photo-count\"></span><div class=\"photo-dots\"></div><button aria-label=\"Previous photo\" data-step=\"-1\" type=\"button\">←</button><button aria-label=\"Next photo\" data-step=\"1\" type=\"button\">→</button></div></div></div><div class=\"day-highlights\"><ul class=\"highlight-list\"><li><strong>Walk the fort and historic streets</strong><p>Explore the ramparts, lighthouse area and streets on foot. Keeping the same accommodation makes this a relaxed cultural day between diving and departure.</p></li></ul><details><summary>More Information</summary><p>Allow 3–5 hours for the old town and a meal. From Unawatuna allow 15–30 minutes each way; from Ahangama roughly 40–60 minutes depending on traffic.</p><a href=\"#sources\">Sources and checks ↗</a></details></div></div><div class=\"stop\" data-date=\"16\" data-thread=\"dec-16\"><div class=\"date\">16 DEC · Apostolos</div><h3>Coast → Negombo</h3><p class=\"sub\">Proposed activities · Overnight Airport area</p><div class=\"travel-links\"><a href=\"https://www.google.com/maps/dir/?api=1&amp;origin=Unawatuna&amp;destination=Negombo&amp;travelmode=driving\" rel=\"noopener\" target=\"_blank\">🚗 Coast → Negombo (3–4.5 h)</a><a href=\"#plans\">⇄ Alternatives</a></div><div class=\"stop-media\"><div class=\"stop-map\"><div class=\"local-map\" data-lat=\"7.211\" data-lon=\"79.835\"></div></div><div aria-label=\"Photos near Negombo\" class=\"gallery\" role=\"region\"><div aria-label=\"Swipe or use the arrow keys to browse photos\" class=\"slides\" tabindex=\"0\"><figure><a href=\"https://commons.wikimedia.org/wiki/File:Negombo_Beach%2C_Sri_Lanka.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Negombo beach\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Negombo_Beach%2C_Sri_Lanka.jpg/500px-Negombo_Beach%2C_Sri_Lanka.jpg\" width=\"500\"/></a><figcaption>Negombo beach · <a href=\"https://commons.wikimedia.org/wiki/File:Negombo_Beach%2C_Sri_Lanka.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Fibreglass_fishing_boat_on_Negombo_Beach.JPG\" rel=\"noopener\" target=\"_blank\"><img alt=\"Fishing boat at Negombo\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Fibreglass_fishing_boat_on_Negombo_Beach.JPG/500px-Fibreglass_fishing_boat_on_Negombo_Beach.JPG\" width=\"500\"/></a><figcaption>Fishing boat at Negombo · <a href=\"https://commons.wikimedia.org/wiki/File:Fibreglass_fishing_boat_on_Negombo_Beach.JPG\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure></div><div class=\"slide-controls\"><span aria-live=\"polite\" class=\"photo-count\"></span><div class=\"photo-dots\"></div><button aria-label=\"Previous photo\" data-step=\"-1\" type=\"button\">←</button><button aria-label=\"Next photo\" data-step=\"1\" type=\"button\">→</button></div></div></div><div class=\"day-highlights\"><ul class=\"highlight-list\"><li><strong>Move north with time to spare</strong><p>Allow roughly 3–4.5 hours from Unawatuna/Ahangama with traffic and breaks. Arrange accommodation near the airport and confirm the following day’s flight before finalising checkout.</p></li></ul><details><summary>More Information</summary><p>The working plan ends diving on 14 December, leaving a generous surface interval. If you add later dives, recheck both flight timing and any altitude exposure.</p><a href=\"#sources\">Sources and checks ↗</a></details></div></div><div class=\"stop\" data-date=\"17\" data-thread=\"dec-17\"><div class=\"date\">17 DEC · Apostolos · provisional</div><h3>Expected departure</h3><p class=\"sub\">Proposed activities · Overnight Return journey</p><div class=\"travel-links\"><a href=\"#flights\">🚗 Accommodation → CMB (pickup time pending)</a><a href=\"#flights\">✈ Return flight (duration pending)</a><a href=\"#plans\">⇄ Alternatives</a></div><div class=\"stop-media\"><div class=\"stop-map\"><div class=\"local-map\" data-lat=\"7.1804\" data-lon=\"79.8841\"></div></div><div aria-label=\"Photos near Colombo Airport\" class=\"gallery\" role=\"region\"><div aria-label=\"Swipe or use the arrow keys to browse photos\" class=\"slides\" tabindex=\"0\"><figure><a href=\"https://commons.wikimedia.org/wiki/File:Negombo_Beach%2C_Sri_Lanka.jpg\" rel=\"noopener\" target=\"_blank\"><img alt=\"Negombo beach\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Negombo_Beach%2C_Sri_Lanka.jpg/500px-Negombo_Beach%2C_Sri_Lanka.jpg\" width=\"500\"/></a><figcaption>Negombo beach · <a href=\"https://commons.wikimedia.org/wiki/File:Negombo_Beach%2C_Sri_Lanka.jpg\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure><figure><a href=\"https://commons.wikimedia.org/wiki/File:Fibreglass_fishing_boat_on_Negombo_Beach.JPG\" rel=\"noopener\" target=\"_blank\"><img alt=\"Fishing boat at Negombo\" height=\"310\" loading=\"lazy\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Fibreglass_fishing_boat_on_Negombo_Beach.JPG/500px-Fibreglass_fishing_boat_on_Negombo_Beach.JPG\" width=\"500\"/></a><figcaption>Fishing boat at Negombo · <a href=\"https://commons.wikimedia.org/wiki/File:Fibreglass_fishing_boat_on_Negombo_Beach.JPG\" rel=\"noopener\" target=\"_blank\">Photo credit &amp; licence</a></figcaption></figure></div><div class=\"slide-controls\"><span aria-live=\"polite\" class=\"photo-count\"></span><div class=\"photo-dots\"></div><button aria-label=\"Previous photo\" data-step=\"-1\" type=\"button\">←</button><button aria-label=\"Next photo\" data-step=\"1\" type=\"button\">→</button></div></div></div><div class=\"day-highlights\"><ul class=\"highlight-list\"><li><strong>Reconfirm the flight</strong><p>Departure date is expected to be 17 December. Exact time and routing are pending; arrange pickup only after reconfirming the ticket.</p></li></ul><details><summary>More Information</summary><p>Allow the airline’s required international check-in margin. Do not assume the previously discussed flight time is booked.</p><a href=\"#sources\">Sources and checks ↗</a></details></div></div></section>\n<section class=\"panel\" data-thread=\"plans\" id=\"plans\"><h2>Compare the working plans</h2><label for=\"plan-select\">Itinerary option</label><select id=\"plan-select\"><option value=\"A\">A · More surfing (default proposal)</option><option value=\"B\">B · More time together</option><option value=\"C\">C · Shared diving</option></select><div aria-live=\"polite\" id=\"plan-detail\"></div><p>Only Maria’s flights and the supplied personal preferences are confirmed. These options change the split-day cards and route map below.</p></section><section class=\"panel\" data-thread=\"hiking\" id=\"hiking\"><h2>Serious hiking choices</h2><p><strong>Horton Plains</strong> · 9 km loop, approximately 200–350 m gain (planning estimate), 3–4 hours, moderate. Visitor-centre start/end; return car from Nuwara Eliya. A guide is optional. Start early, carry waterproofs and a warm layer; mist can arrive quickly. Maria’s participation is pending.</p><p><strong>Pekoe Stage 13</strong> · 14.6 km, +810/−360 m, official 4 hours; plan 5–6. Haputale → St Catherine, point-to-point pickup required. Officially moderate with sustained ascent. Guide recommended if navigation or visibility is poor. November advisory reports leeches and overgrowth. Reconfirm trail access/pass arrangements.</p><p><strong>Ella Rock</strong> · provisional 8–12 km, +400–600 m, 4–6 hours, moderate to demanding. Obtain a guide-confirmed road-access start/end and track avoiding the railway. Figures vary with that route and are not a surveyed itinerary. December rain makes roots and slopes slippery. Little Adam’s Peak remains a short fallback.</p><p><strong>Knuckles alternative</strong> · for remote forest trekking, replace Kandy/highland days and allow at least two additional nights rather than append it. A guided 10–16 km day with roughly 600–1,000 m ascent and 6–8 hours is a planning envelope, not a selected trail. Guide, exact trailhead, permits and return vehicle must be arranged. December northeast-monsoon rain can make river crossings unsafe. This option sacrifices coast or Ella time. Adam’s Peak is not the default.</p></section><section class=\"panel\" data-thread=\"diving\" id=\"diving\"><h2>Advanced recreational diving</h2><p>Both travellers hold Advanced Open Water certification. Choose sites with an operator after reviewing recent logged dives, sea conditions and depth limits. Use external wreck tours only; certification alone does not cover penetration, decompression or technical diving.</p><table><thead><tr><th>Area / site</th><th>Character and depth</th><th>Fit</th></tr></thead><tbody><tr><td>Unawatuna reefs and rock sites</td><td>Many reefs to around 18 m; deeper rocky valleys</td><td>Good first dive to assess conditions and buoyancy</td></tr><tr><td>Galle Ship Wreck</td><td>Wreck · around 18 m</td><td>Recreational exterior tour</td></tr><tr><td>SS Orestes</td><td>Wreck · around 22 m</td><td>AOW candidate with suitable conditions</td></tr><tr><td>Rangoon</td><td>Wreck · operator reports vary 30–32 m</td><td>Only if actual profile stays within your qualifications; otherwise choose another site</td></tr><tr><td>Hikkaduwa</td><td>Reef and wreck choices; site/depth to agree with operator</td><td>Alternative if conditions justify a longer transfer</td></tr></tbody></table><p><a href=\"https://www.unawatunadiving.com/unawatuna/\" rel=\"noopener\" target=\"_blank\">Unawatuna Diving Centre</a> advertises certified dives and a PADI 5 Star IDC operation. Published two-tank rates are €60 with own equipment or €70 with rental equipment; reconfirm inclusions and availability. <a href=\"https://www.poseidondive.com/\" rel=\"noopener\" target=\"_blank\">Poseidon Diving Station, Hikkaduwa</a> is a candidate to enquire with, not a booked or independently audited recommendation. Ask about group ratios, emergency oxygen, boat support and cancellation terms.</p><p>December is within the south-coast operating season. Visibility varies with rain, runoff and swell; do not rely on a fixed visibility range or guaranteed departure. From Ahangama allow about 30–60 minutes to Unawatuna, 1–1.5 hours to Hikkaduwa; Weligama may add 20–30 minutes. Local Weligama/Mirissa operators can reduce transfers if they confirm suitable reef/wreck profiles.</p><p><strong>Maria alone</strong> · morning dives on 11 December instead of surfing. <strong>Apostolos</strong> · 13–14 December. <strong>Together</strong> · Option C, 11 December, requires a mountain-day trade-off.</p><p class=\"warn\">Use at least 24 hours from the final dive to Maria’s 20:05 flight on 12 December; a morning finish on 11 December is preferable. No diving on 12 December. DAN recommends minimum 12 hours after a single no-stop dive and 18 hours after repetitive/multiday diving; longer intervals reduce risk. Decompression dives require substantially longer. Apply dive-computer and professional guidance, including before driving back to mountain altitude. Keep all mountain hiking before the coast dives.</p></section><section class=\"panel\" data-thread=\"surfing\" id=\"surfing\"><h2>Maria’s intermediate surfing</h2><ul class=\"highlight-list\"><li><strong>Ahangama / Kabalana</strong><p>A practical base for several breaks and access west to Unawatuna. The Rock is a powerful reef A-frame for confident intermediates in suitable swell. The beach break offers a softer alternative when the reef is too demanding.</p></li><li><strong>Midigama</strong><p>Lazy Left and Lazy Right offer longer reef rides when the swell is manageable. Ask a local guide about tide, entry/exit and reef exposure. Rams is a more consequential advanced break and is not the default.</p></li><li><strong>Weligama</strong><p>A sheltered sandy-bay fallback, useful for technique or smaller days. It need not mean a beginner lesson. Hire a board suited to the actual conditions or take an intermediate coaching session.</p></li></ul><details><summary>More Information</summary><p>November–April is the main south-coast season. Early mornings often have lighter wind; inspect tide and swell rather than using a fixed daily session time. Tuk-tuks with proper board racks link the towns in roughly 10–30 minutes. Confirm hire prices locally. A guesthouse near Ahangama or Midigama reduces daily transfers; hostel versus private room remains Maria’s choice. Keep a dive day separate from a strenuous surf session where possible.</p></details></section><section class=\"panel\" data-thread=\"practical\" id=\"practical\"><h2>Transfers, wildlife and weather</h2><p><strong>Train status</strong> · Sri Lanka Railways announced restoration of Badulla–Nanu Oya services in June 2026. This supports a possible Nanu Oya–Ella journey but does not confirm a train or seats on 9 December. Recheck the official timetable/reservations shortly before travel. If unavailable, use the 2.5–3.5-hour road fallback; buses can require changes and substantially more time.</p><p><strong>Private transfers matter most</strong> · arrival day, the long Kandy transfer, Maria’s independent coast transfer and airport day, and the Udawalawe connection. Published driving estimates vary widely; the ranges on the cards include planning allowance, not a live routing prediction. Obtain door-to-door quotes and reconfirm pickup times.</p><p><strong>Udawalawe working safari</strong> · elephant-focused grassland/reservoir landscapes fit the southwest journey. Budget around three hours in the park. Yala is an alternative if leopard habitat is the priority, with a detour towards Tissamaharama and roughly 3–4 hours onward to the coast. Allow a safari-base overnight for Yala. No sightings are guaranteed.</p><p><strong>December weather</strong> · northeast-monsoon exposure is stronger in the north/east, while the southwest is in its usual surf/dive season. The central highlands can still be cold, wet and misty. Reserve hiking mornings, keep a wet-weather rest/tea-estate option, and let operators cancel unsafe ocean outings.</p><p><strong>Access and bookings</strong> · Horton Plains is commonly listed 06:00–18:00, but confirm hours, permits and last entry with DWC. Confirm safari gate times with the booked operator. Accommodation and transport availability have not been checked for specific properties; December is busy on the south coast. Pick flexible reservations once Maria confirms the split.</p></section><section class=\"panel\" data-thread=\"questions\" id=\"questions\"><h2>Questions for Maria</h2><p>Known answers are prefilled. All remaining decisions are pending. Save answers to share across devices, then copy them into a message for the next itinerary revision.</p><form id=\"questionnaire\"></form><button id=\"save-answers\" type=\"button\">Save answers</button> <button id=\"copy-answers\" type=\"button\">Copy answers</button><p id=\"answer-status\" role=\"status\"></p><textarea aria-label=\"Answers ready to copy\" hidden=\"\" id=\"copy-output\" readonly=\"\"></textarea></section><section class=\"panel\" data-thread=\"sources\" id=\"sources\"><h2>Sources and outstanding decisions</h2><p>Research checked 14 November 2026. Future operations and weather remain subject to change.</p><ul><li><a href=\"https://thepekoetrail.org/pekoe-stages/stage-13/\" rel=\"noopener\" target=\"_blank\">Pekoe Stage 13 and current advisory ↗</a></li><li><a href=\"https://tourism.cp.gov.lk/en/horton-plains\" rel=\"noopener\" target=\"_blank\">Horton Plains · Central Province Tourism ↗</a></li><li><a href=\"https://www.railway.gov.lk/web/\" rel=\"noopener\" target=\"_blank\">Sri Lanka Railways ↗</a></li><li><a href=\"https://seatreservation.railway.gov.lk/mtktwebslr/\" rel=\"noopener\" target=\"_blank\">Official seat reservations ↗</a></li><li><a href=\"https://world.dan.org/health-medicine/health-resources/diseases-conditions/flying-after-diving/\" rel=\"noopener\" target=\"_blank\">DAN flying-after-diving guidance ↗</a></li><li><a href=\"https://www.unawatunadiving.com/unawatuna/dive-sites-in-sri-lanka.html\" rel=\"noopener\" target=\"_blank\">Unawatuna dive sites ↗</a></li><li><a href=\"https://www.unawatunadiving.com/unawatuna/rates.html\" rel=\"noopener\" target=\"_blank\">Unawatuna published rates ↗</a></li><li><a href=\"https://surfsouthsrilanka.com/midigama-lazy-left/\" rel=\"noopener\" target=\"_blank\">Midigama local surf guide ↗</a></li><li><a href=\"https://surfsouthsrilanka.com/kabalana-the-rock/\" rel=\"noopener\" target=\"_blank\">Kabalana local surf guide ↗</a></li><li><a href=\"https://www.dwc.gov.lk/\" rel=\"noopener\" target=\"_blank\">Wildlife permits and access ↗</a></li><li><a href=\"https://ceilontravels.com/sri-lanka-driving-times\" rel=\"noopener\" target=\"_blank\">Driving estimates ↗</a></li><li><a href=\"https://lankan.lk/travel/places/nuwara-eliya\" rel=\"noopener\" target=\"_blank\">Long coast-transfer planning ↗</a></li></ul><p>Confirm Maria’s independent transfer, Horton Plains participation, surf/dive balance, shared diving preference, driver budget and accommodation style. Reconfirm Apostolos’s return flight, hiking guide/routes, park access, train seats and dive operators.</p></section></main><aside><section class=\"panel mapwrap\" data-thread=\"map\"><h2>Routes and activities</h2><p class=\"sub\">Shared · green | Apostolos · blue | Maria · purple. Dashed alternatives are unconfirmed. Lines connect stops schematically, not road navigation.</p><div class=\"map\" id=\"map\"></div><p id=\"map-state\"></p></section></aside></div><footer>Working itinerary · updated 14 November 2026 · Maria’s flights confirmed; activities and split provisional. Map data © OpenStreetMap contributors.</footer>\n<script crossorigin=\"\" integrity=\"sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=\" src=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.js\"></script>\n<script>const threads = new Map();\nconst mark = window.Highlight ? new Highlight() : null;\nif (mark) CSS.highlights.set('commented-text', mark);\n\nfor (const gallery of document.querySelectorAll('.gallery')) {\n  const slides = gallery.querySelector('.slides');\n  const count = slides.children.length;\n  const counter = gallery.querySelector('.photo-count');\n  const dots = gallery.querySelector('.photo-dots');\n  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');\n  const current = () => Math.max(0, Math.min(count - 1, Math.round(slides.scrollLeft / slides.clientWidth)));\n  function go(index) {\n    slides.scrollTo({left: ((index + count) % count) * slides.clientWidth,\n      behavior: reduceMotion.matches ? 'instant' : 'smooth'});\n  }\n  for (let index = 0; index < count; index++) {\n    const dot = document.createElement('button');\n    dot.type = 'button';\n    dot.setAttribute('aria-label', 'Show photo ' + (index + 1));\n    dot.addEventListener('click', () => go(index));\n    dots.append(dot);\n  }\n  function update() {\n    const index = current();\n    const label = (index + 1) + ' / ' + count;\n    if (counter.textContent === label) return;\n    counter.textContent = label;\n    [...dots.children].forEach((dot, i) => dot.setAttribute('aria-current', String(i === index)));\n  }\n  update();\n  slides.addEventListener('scroll', update, {passive:true});\n  slides.addEventListener('keydown', event => {\n    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;\n    event.preventDefault();\n    go(current() + (event.key === 'ArrowLeft' ? -1 : 1));\n  });\n  gallery.addEventListener('click', event => {\n    const step = Number(event.target.dataset.step);\n    if (step) go(current() + step);\n  });\n  }\n\nfor (const image of document.querySelectorAll('.gallery img,.option-photo img')) {\n    image.addEventListener('error', () => {\n      if (image.dataset.retry) {\n        image.replaceWith(document.createTextNode('Open ' + image.alt + ' on Wikimedia Commons'));\n        return;\n      }\n      image.dataset.retry = 'true';\n      image.src = image.src.replace('/commons/thumb/', '/commons/').replace(/\\/500px-[^/]+$/, '');\n    });\n}\n\nfunction locateQuote(section, quote) {\n  const nodes = [...section.querySelectorAll('h2,h3,p,li,.date,.sub,.warn')];\n  for (const node of nodes) {\n    if (node.closest('[data-thread]') !== section || node.closest('.thread')) continue;\n    let offset = node.textContent.indexOf(quote);\n    if (offset < 0) continue;\n    const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);\n    const range = document.createRange();\n    let end = offset + quote.length;\n    let startSet = false;\n    while (walker.nextNode()) {\n      const text = walker.currentNode;\n      if (!startSet && offset < text.length) {\n        range.setStart(text, offset);\n        startSet = true;\n      }\n      if (startSet && end <= text.length) {\n        range.setEnd(text, end);\n        return range;\n      }\n      offset -= text.length;\n      end -= text.length;\n    }\n  }\n}\n\nfor (const section of document.querySelectorAll('[data-thread]')) {\n  const thread = document.createElement('div');\n  thread.className = 'thread';\n  thread.innerHTML = '<button class=\"thread-icon\" type=\"button\" aria-label=\"Open comments\" aria-expanded=\"false\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" width=\"19\" height=\"19\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M4 5h16v12H9l-5 4z\"/></svg><span class=\"comment-count\"></span></button><div class=\"comment-box\" popover aria-label=\"Comments\"><div class=\"comment-heading\"><strong>Comments</strong><button class=\"comment-close\" type=\"button\" aria-label=\"Close comments\">×</button></div><div class=\"messages\" aria-live=\"polite\"></div><form><blockquote hidden></blockquote><label>Post as<select required><option value=\"\">Choose a name</option><option>Maria</option><option>Apostolis</option><option>Giannis</option></select></label><label>Leave a comment<textarea required maxlength=\"2000\" rows=\"3\"></textarea></label><button type=\"submit\">Post comment</button> <button type=\"button\" hidden>Clear selection</button><span role=\"status\"></span></form></div>';\n  const icon = thread.querySelector('.thread-icon');\n  const box = thread.querySelector('.comment-box');\n  const close = thread.querySelector('.comment-close');\n  const namePicker = thread.querySelector('select');\n  function positionBox() {\n    const anchor = icon.getBoundingClientRect();\n    box.style.left = Math.max(8, Math.min(anchor.left, innerWidth - box.offsetWidth - 8)) + 'px';\n    const below = anchor.bottom + 6;\n    box.style.top = Math.max(8, Math.min(below, innerHeight - box.offsetHeight - 8)) + 'px';\n  }\n  function openBox() {\n    if (!box.matches(':popover-open')) box.showPopover();\n    positionBox();\n  }\n  icon.addEventListener('click', () => {\n    if (box.matches(':popover-open')) box.hidePopover();\n    else openBox();\n  });\n  close.addEventListener('click', () => { box.hidePopover(); icon.focus(); });\n  section.append(thread);\n  const list = thread.querySelector('.messages');\n  const form = thread.querySelector('form');\n  const button = form.querySelector('[type=submit]');\n  const clear = form.querySelector('[type=button]');\n  const excerpt = form.querySelector('blockquote');\n  const status = form.querySelector('[role=status]');\n  const input = form.querySelector('textarea');\n  const endpoint = '/api/comments?section=' + encodeURIComponent(section.dataset.thread);\n  let quote = '';\n  let highlights = [];\n  function attach(value) {\n    quote = value;\n    excerpt.textContent = value;\n    excerpt.hidden = clear.hidden = !value;\n  }\n  clear.addEventListener('click', () => attach(''));\n  threads.set(section, {start(value) {\n    attach(value);\n    openBox();\n    input.focus();\n  }});\n\n  async function refresh() {\n    try {\n      const result = await fetch(endpoint);\n      if (!result.ok) throw new Error();\n      const comments = await result.json();\n      if (mark) for (const range of highlights) mark.delete(range);\n      highlights = [];\n      list.replaceChildren();\n      if (!comments.length) list.textContent = 'No comments yet. Select itinerary text to comment on a passage.';\n      for (const comment of comments) {\n        const entry = document.createElement('article');\n        const name = document.createElement('strong');\n        const body = document.createElement('p');\n        name.textContent = comment.author;\n        body.textContent = comment.body;\n        entry.append(name);\n        if (comment.quote) {\n          const citation = document.createElement('blockquote');\n          const jump = document.createElement('a');\n          jump.href = '#';\n          jump.textContent = comment.quote;\n          const range = locateQuote(section, comment.quote);\n          if (range && mark) {mark.add(range); highlights.push(range);}\n          jump.addEventListener('click', event => {\n            event.preventDefault();\n            if (!range) return;\n            range.startContainer.parentElement.scrollIntoView({block: 'center'});\n            const selection = window.getSelection();\n            selection.removeAllRanges();\n            selection.addRange(range.cloneRange());\n          });\n          citation.append(jump);\n          entry.append(citation);\n        }\n        entry.append(body);\n        list.append(entry);\n      }\n      thread.querySelector('.comment-count').textContent = comments.length || '';\n      icon.setAttribute('aria-label', 'Open comments (' + comments.length + ')');\n      if (box.matches(':popover-open')) positionBox();\n    } catch {\n      list.textContent = 'Comments could not load. Close and reopen this thread to retry.';\n    }\n  }\n  box.addEventListener('toggle', () => {\n    const open = box.matches(':popover-open');\n    icon.setAttribute('aria-expanded', String(open));\n    if (open) refresh();\n  });\n  const reposition = () => { if (box.matches(':popover-open')) positionBox(); };\n  window.addEventListener('resize', reposition);\n  window.addEventListener('scroll', reposition, {passive:true});\n  refresh();\n  form.addEventListener('submit', async event => {\n    event.preventDefault();\n    if (!input.value.trim()) return;\n    status.textContent = '';\n    button.disabled = true;\n    try {\n      const result = await fetch(endpoint, {\n        method: 'POST',\n        headers: {'Content-Type': 'application/json'},\n        body: JSON.stringify({body: input.value, quote, author: namePicker.value})\n      });\n      if (!result.ok) throw new Error();\n      input.value = '';\n      attach('');\n      status.textContent = 'Posted.';\n      await refresh();\n    } catch {\n      status.textContent = 'Could not post the comment. Please retry.';\n    } finally {\n      button.disabled = false;\n    }\n  });\n}\n\nconst selectionButton = document.createElement('button');\nselectionButton.type = 'button';\nselectionButton.className = 'selection-comment';\nselectionButton.textContent = 'Comment on selection';\nselectionButton.hidden = true;\ndocument.body.append(selectionButton);\nlet pending;\ndocument.addEventListener('selectionchange', () => {\n  const selection = window.getSelection();\n  const quote = selection.toString().trim();\n  const find = node => (node?.parentElement)?.closest('[data-thread]');\n  const section = find(selection.anchorNode);\n  if (!quote || quote.length > 500 || !section || section !== find(selection.focusNode)\n    || selection.anchorNode.parentElement.closest('.thread,.stop-media')\n    || selection.focusNode.parentElement.closest('.thread,.stop-media')) {\n    selectionButton.hidden = true;\n    return;\n  }\n  pending = {section, quote};\n  const bounds = selection.getRangeAt(0).getBoundingClientRect();\n  selectionButton.style.left = Math.max(4, Math.min(bounds.left, window.innerWidth - 170)) + 'px';\n  selectionButton.style.top = Math.min(bounds.bottom + 8, window.innerHeight - 38) + 'px';\n  selectionButton.hidden = false;\n});\nselectionButton.addEventListener('pointerdown', event => event.preventDefault());\nselectionButton.addEventListener('click', () => {\n  if (!pending) return;\n  threads.get(pending.section).start(pending.quote);\n  selectionButton.hidden = true;\n});\nwindow.addEventListener('scroll', () => {selectionButton.hidden = true;}, {passive:true});\n</script><script>const planTexts={\n A:'Proposed split on 9 December. Maria has full coast days on 10 and 11 December; Apostolos keeps Stage 13 and Ella Rock. Maria chooses two surf days or one surf day plus a dive day.',\n B:'Stay together in Ella/Haputale on 9–10 December for Stage 13 if Maria wants it. Maria travels to the coast on 11 December (allow 4–5 hours), leaving at most a short late surf session. No full dive day is assumed. Airport transfer remains 12 December.',\n C:'Travel together to Ella on 9 December. Move Ella Rock to early 10 December, then drive to the coast that afternoon (a demanding combined day). This removes Stage 13 from this trip, unless you redesign earlier days. Dive together on the morning of 11 December. A gentler variant skips Ella Rock and keeps 10 December as a transfer day. Both require agreement.'\n};\nconst selector=document.querySelector('#plan-select');\nconst points=[\n ['1 · CMB arrival','5 Dec · together · immigration and transfer',7.1804,79.8841,'✈'],\n ['2 · Sigiriya','5–6 Dec · culture · full day',7.957,80.7603,'🏛'],\n ['3 · Dambulla','6 Dec · caves · 1.5–2 hours',7.856,80.649,'🏛'],\n ['4 · Kandy','7 Dec · temple if time allows · 1–2 hours',7.2936,80.6413,'🏛'],\n ['5 · Nuwara Eliya','7–9 Dec · proposed overnight base; hotel unselected',6.9497,80.7891,'🛏'],\n ['6 · Horton Plains','8 Dec · shared hike pending · 3–4 hours',6.802,80.807,'🥾'],\n ['7 · Ella','9–11 Dec · hiking base · proposed',6.8667,81.0466,'🥾'],\n ['8 · Haputale','10 Dec · Stage 13 start · 5–6 hours',6.768,80.958,'🥾'],\n ['9 · Udawalawe','12 Dec · safari · around 3 hours',6.438,80.889,'🐘'],\n ['10 · Ahangama','Maria 9–12 Dec in A · surf base, hotel unselected',5.974,80.363,'🏄'],\n ['11 · Unawatuna','11 Dec Maria or shared option; 13–14 Dec Apostolos · diving',6.01,80.249,'🤿'],\n ['12 · Galle','15 Dec · cultural day trip · 3–5 hours',6.0269,80.217,'🏛'],\n ['13 · Negombo','16 Dec · proposed airport-area stay',7.211,79.835,'🛏'],\n ['14 · CMB departure','Maria 12 Dec 20:05, target 16:00; Apostolos 17 Dec provisional',7.1804,79.8841,'✈']\n];\nlet mainMap,routeLayers;\nconst position=i=>[points[i][2],points[i][3]];\nfunction drawRoutes(plan){\n if(!mainMap)return;\n routeLayers.clearLayers();\n const add=(ids,color,dash)=>L.polyline(ids.map(position),{color,weight:4,dashArray:dash}).addTo(routeLayers);\n add([0,1,2,3,4,5,4],'#146c61');\n if(plan==='A'){add([4,6,7,6,8,10,11,12,13],'#2466b0');add([4,9,13],'#9356ab');}\n if(plan==='B'){add([4,6,7,6],'#146c61');add([6,8,10,11,12,13],'#2466b0');add([6,9,13],'#9356ab');}\n if(plan==='C'){add([4,6,9,10],'#146c61');add([10,13],'#9356ab');add([10,8,10,11,12,13],'#2466b0','5 6');}\n document.querySelector('#map-state').textContent='Option '+plan+' · proposed routes. '+(plan==='C'?'Safari must move to 12 December as a coast-based round trip (around 5–7 hours driving plus safari), or an overnight stay.':'Maria’s confirmed airport departure is 12 December at 20:05.');\n}\nfunction choosePlan(){\n const p=selector.value;\n document.querySelector('#plan-detail').textContent=planTexts[p];\n document.querySelectorAll('.variant-note').forEach(n=>n.remove());\n if(p!=='A')for(const day of ['9','10','11','12']){\n  const card=document.querySelector('[data-date=\"'+day+'\"]');\n  const note=document.createElement('p');note.className='variant-note';\n  note.textContent='Option '+p+' replaces the default activity below. '+planTexts[p]+(p==='C'&&day==='12'?' Udawalawe becomes a separate coast-based excursion or requires an overnight.':'');\n  card.querySelector('.day-highlights').before(note);\n  card.querySelector('.day-highlights').hidden=true;\n }\n if(p==='A')document.querySelectorAll('.day-highlights').forEach(n=>n.hidden=false);\n drawRoutes(p);\n}\nselector.addEventListener('change',choosePlan);\nif(window.L){\n document.body.classList.add('ready');\n mainMap=L.map('map',{scrollWheelZoom:false});\n const tiles=()=>L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19,referrerPolicy:'strict-origin-when-cross-origin',updateWhenIdle:true,keepBuffer:1});\n tiles().addTo(mainMap);routeLayers=L.layerGroup().addTo(mainMap);\n for(const point of points){\n  const marker=L.marker([point[2],point[3]],{icon:L.divIcon({className:'activity-marker',html:'<span style=\"background:white;border:1px solid #146c61;border-radius:50%;padding:4px\">'+point[4]+'</span>',iconSize:[28,28]})}).addTo(mainMap);\n  const box=document.createElement('div'),heading=document.createElement('strong'),body=document.createElement('p'),a=document.createElement('a');\n  heading.textContent=point[0];body.textContent=point[1];a.textContent='Navigation ↗';a.target='_blank';a.rel='noopener';\n  a.href='https://www.google.com/maps/search/?api=1&query='+point[2]+','+point[3];box.append(heading,body,a);marker.bindPopup(box);\n }\n for(const [name,lat,lon] of [['Alternative · Yala',6.28,81.287],['Alternative · Hikkaduwa diving',6.14,80.10],['Alternative · Knuckles trekking',7.45,80.8]]){\n  L.circleMarker([lat,lon],{color:'#777',fillOpacity:0,dashArray:'3 4',radius:8}).addTo(mainMap).bindPopup(name+' · unconfirmed');\n }\n mainMap.fitBounds(points.map(p=>[p[2],p[3]]),{padding:[20,20]});\n const cards=[...document.querySelectorAll('.local-map')];\n const initialiseMap=(element,i)=>{\n  const dest=[+element.dataset.lat,+element.dataset.lon];\n  const map=L.map(element,{scrollWheelZoom:false}).setView(dest,10);tiles().addTo(map);\n  L.circleMarker(dest,{radius:6,color:'#146c61'}).addTo(map);\n  if(i){const prev=cards[i-1];L.polyline([[+prev.dataset.lat,+prev.dataset.lon],dest],{color:'#2466b0',weight:3}).addTo(map);}\n  new ResizeObserver(()=>map.invalidateSize()).observe(element);\n };\n const visibleMaps=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){visibleMaps.unobserve(entry.target);initialiseMap(entry.target,cards.indexOf(entry.target));}}},{rootMargin:'0px'});\n cards.forEach(element=>visibleMaps.observe(element));\n}else document.querySelector('#map-state').textContent='Map library unavailable. Use the navigation links on each day card.';\nchoosePlan();\nconst questions=[\n ['Flights','Confirmed: CMB arrival 5 Dec 08:10; departure 12 Dec 20:05.'],\n ['Surfing level','Intermediate'],['Water sports','Surfing and scuba diving'],['Diving certification','Advanced Open Water'],\n ['Surfing versus shared hiking',''],['Independent transfer on 9 December',''],['Horton Plains participation',''],['Two surf days or surf plus diving',''],['Diving together and the mountain trade-off',''],['Private driver budget',''],['Accommodation style',''],['Additional preferences','']\n];\nconst form=document.querySelector('#questionnaire'),status=document.querySelector('#answer-status');\nquestions.forEach(([label,value],i)=>{\n const wrapper=document.createElement('label');wrapper.textContent=(i+1)+'. '+label+(value?' · supplied answer':' · pending');\n const field=document.createElement('textarea');field.name=String(i);field.value=value;field.placeholder='Pending — add your answer';\n wrapper.append(field);form.append(wrapper);\n});\nlet revision=0;\nasync function loadAnswers(){\n try{const response=await fetch('/api/answers');if(!response.ok)throw new Error();const data=await response.json();revision=data.revision;for(const [key,value]of Object.entries(data.answers))if(form.elements.namedItem(key))form.elements.namedItem(key).value=value;\n status.textContent='Saved answers loaded. Blank answers remain pending.';\n }catch{status.textContent='Could not load shared answers. Supplied answers remain visible; retry before saving.';document.querySelector('#save-answers').disabled=true;}\n}\ndocument.querySelector('#save-answers').addEventListener('click',async()=>{\n const button=document.querySelector('#save-answers');button.disabled=true;\n try{const response=await fetch('/api/answers',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({answers:Object.fromEntries(new FormData(form)),revision})});if(response.status===409){status.textContent='Someone updated these answers. Copy your draft, then reload before saving.';return;}if(!response.ok)throw new Error();revision=(await response.json()).revision;status.textContent='Answers saved. The itinerary remains provisional until reviewed.';}catch{status.textContent='Save failed. Your answers remain in the form.';}finally{button.disabled=false;}\n});\ndocument.querySelector('#copy-answers').addEventListener('click',async()=>{\n const value=questions.map(([label],i)=>(i+1)+'. '+label+'\\n'+(form.elements.namedItem(String(i)).value.trim()||'Pending')).join('\\n\\n');\n try{await navigator.clipboard.writeText(value);status.textContent='Answers copied.';}catch{const out=document.querySelector('#copy-output');out.hidden=false;out.value=value;out.select();status.textContent='Select and copy the answers below.';}\n});\nloadAnswers();\n</script></body></html>\n";
const sections = new Set(["alternatives", "booking", "day-1", "day-10", "day-11", "day-2", "day-3", "day-4", "day-5", "day-6", "day-7", "day-8", "day-9", "dec-10", "dec-11", "dec-12", "dec-13", "dec-14", "dec-15", "dec-16", "dec-17", "dec-5", "dec-6", "dec-7", "dec-8", "dec-9", "diving", "flights", "hiking", "itinerary", "map", "plans", "practical", "questions", "route", "sources", "surfing", "transport"]);

import { sqliteStore } from './storage.mjs';

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const store = env.STORE || sqliteStore(env.DB);
    if (url.pathname === '/' && request.method === 'GET') {
      return new Response(html, {
        headers: {'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'private, no-store', 'Referrer-Policy': 'strict-origin-when-cross-origin'}
      });
    }
    if (url.pathname === '/api/answers') {
      if (!request.headers.get('oai-authenticated-user-id')) return new Response(null,{status:401});
      if(request.method==='GET'){
        return Response.json(await store.getAnswers(),{headers:{'Cache-Control':'no-store'}});
      }
      if(request.method!=='POST') return new Response(null,{status:405});
      if(request.headers.get('Origin')!==url.origin) return new Response(null,{status:403});
      const payload=await request.json().catch(()=>null);
      if(!payload||!Number.isInteger(payload.revision)||!payload.answers||Array.isArray(payload.answers))return new Response(null,{status:400});
      const entries=Object.entries(payload.answers);
      if(entries.length!==12||entries.some(([k,v])=>!/^([0-9]|1[01])$/.test(k)||typeof v!=='string'||v.length>3000))return new Response(null,{status:400});
      const revision=await store.saveAnswers(payload.answers,payload.revision);
      if(revision===null)return new Response(null,{status:409});
      return Response.json({revision});
    }

    if (url.pathname !== '/api/comments') return new Response(null, {status: 404});
    const user = request.headers.get('oai-authenticated-user-id');
    if (!user) return new Response(null, {status: 401});

    const section = url.searchParams.get('section');
    if (!sections.has(section)) return new Response(null, {status: 400});
    if (request.method === 'GET') {
      return Response.json(await store.getComments(section), {headers: {'Cache-Control': 'private, no-store', 'Referrer-Policy': 'strict-origin-when-cross-origin'}});
    }
    if (request.method !== 'POST') return new Response(null, {status: 405});
    if (request.headers.get('Origin') !== url.origin) return new Response(null, {status: 403});

    const payload = await request.json().catch(() => null);
    const body = typeof payload?.body === 'string' ? payload.body.trim() : '';
    const quote = typeof payload?.quote === 'string' ? payload.quote.trim() : '';
    if (!body || body.length > 2000 || quote.length > 500) return new Response(null, {status: 400});

    const author = payload?.author;
    if (!['Maria', 'Apostolis', 'Giannis'].includes(author)) {
      return new Response(null, {status: 400});
    }
    await store.addComment(section, author, body, quote);
    return new Response(null, {status: 201});
  }
};
